def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Base bid: competitive but not reckless.
    # If supply is near upper end, bidding higher is less costly (more water available).
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_factor = 0.62 if float(supply) >= supply_mid else 0.55

    # React to my own criticality.
    # If I'm low HP or have already accumulated no-water days, increase bid.
    if hp <= 2:
        my_factor = 0.90
    elif hp <= 3:
        my_factor = 0.75
    else:
        my_factor = supply_factor

    # If budget is tight relative to daily salary, scale down to avoid going broke.
    # Keep at least enough to stay in the game.
    if DAILY_SALARY > 0:
        budget_factor = min(1.0, float(budget) / float(DAILY_SALARY))
    else:
        budget_factor = 0.2

    target = DAILY_SALARY * my_factor * max(0.35, budget_factor)

    # If there is any immediate signal from opponents' previous_trace, adjust slightly.
    # Only use the most recent (yesterday) bid if available.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev:
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they were bidding aggressively, match modestly; otherwise keep base.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, DAILY_SALARY * 0.65)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            target = max(target, highest_prev_bid * 0.95)

    # Final cap by budget and enforce non-negative.
    if budget <= 0:
        return 0
    bid = min(float(budget), float(target))
    if bid < 0:
        bid = 0

    # Convert to a reasonable integer bid (game typically expects numeric; safe to round).
    return int(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return max(0.0, min(float(budget), DAILY_SALARY * 0.2))

    player_count = 1 + len(alive_opponents)
    coverage = supply / float(WATER_REQ * player_count)

    highest_prev = max(prev_bids) if prev_bids else None
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else None

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if coverage < 0.45:
        urgency += 2
    elif coverage < 0.7:
        urgency += 1

    base = DAILY_SALARY * 0.42

    if highest_prev is not None:
        if highest_prev >= DAILY_SALARY * 0.9:
            if urgency >= 4:
                base = DAILY_SALARY * 0.96
            elif urgency >= 2:
                base = DAILY_SALARY * 0.78
            else:
                base = DAILY_SALARY * 0.28
        elif highest_prev >= DAILY_SALARY * 0.7:
            if urgency >= 4:
                base = min(DAILY_SALARY * 0.92, highest_prev + 2.0)
            elif urgency >= 2:
                base = max(DAILY_SALARY * 0.62, highest_prev * 0.88)
            else:
                base = DAILY_SALARY * 0.36
        else:
            if urgency >= 4:
                base = max(DAILY_SALARY * 0.72, highest_prev + 3.0)
            elif urgency >= 2:
                base = max(DAILY_SALARY * 0.56, highest_prev + 1.5)
            else:
                base = max(DAILY_SALARY * 0.35, highest_prev * 0.9)
    else:
        if urgency >= 5:
            base = DAILY_SALARY * 0.9
        elif urgency >= 3:
            base = DAILY_SALARY * 0.68
        elif urgency >= 1:
            base = DAILY_SALARY * 0.5
        else:
            base = DAILY_SALARY * 0.38

    if desperate_count >= max(1, len(alive_opponents) // 2):
        base += 4.0
    if rich_count >= max(1, len(alive_opponents) // 2):
        base += 3.0

    if avg_prev is not None and highest_prev is not None and highest_prev - avg_prev > DAILY_SALARY * 0.25 and urgency <= 2:
        base -= 4.0

    if coverage >= 0.9 and urgency <= 2:
        base *= 0.82
    elif coverage <= 0.35:
        base *= 1.12

    reserve_target = 0.0
    days_left_est = max(0, 10 - int(day_context['day']))
    if days_left_est > 0:
        reserve_target = min(budget * 0.55, days_left_est * DAILY_SALARY * 0.28)

    affordable = budget
    if urgency <= 1:
        affordable = max(0.0, budget - reserve_target)
    elif urgency == 2:
        affordable = max(0.0, budget - reserve_target * 0.5)

    bid = min(base, affordable if affordable > 0 else budget)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(float(budget), DAILY_SALARY * 0.93))
    elif hp <= 4 and no_water >= 1:
        bid = max(bid, min(float(budget), DAILY_SALARY * 0.8))

    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, DAILY_SALARY * 0.98)

    if bid < 0:
        bid = 0.0
    return float(bid)
